-- OFFLINE isolated PG17 fixture only. Never install into a production migration.
DO $$BEGIN IF (current_database()<>'design_executor_synthetic' OR current_setting('design_executor.synthetic_fixture',true) IS DISTINCT FROM 'offline-stage6-only' OR current_setting('server_version_num')::int/10000<>17 OR to_regnamespace('design_dependency_authority') IS NULL OR to_regnamespace('design_managed_image') IS NOT NULL) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_FIXTURE_REQUIRED';END IF;END$$;
CREATE ROLE design_managed_storage_issuer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_managed_processing_issuer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_managed_cost_issuer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_managed_preflight_issuer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_managed_image_capability NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
GRANT CONNECT ON DATABASE design_executor_synthetic TO design_managed_storage_issuer,design_managed_processing_issuer,design_managed_cost_issuer,design_managed_preflight_issuer;
CREATE SCHEMA design_managed_image AUTHORIZATION design_identity_owner;
REVOKE ALL ON SCHEMA design_managed_image FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA design_managed_image TO design_identity_runtime,design_managed_storage_issuer,design_managed_processing_issuer,design_managed_cost_issuer,design_managed_preflight_issuer,design_managed_image_capability;
GRANT CREATE ON SCHEMA design_managed_image TO design_managed_image_capability;
GRANT USAGE ON SCHEMA design_identity,design_dependency_authority TO design_managed_image_capability;
GRANT EXECUTE ON FUNCTION design_identity.require_authority(),design_identity.resolve_hash(text,jsonb),design_dependency_authority.digest(jsonb),design_dependency_authority.canonical(jsonb) TO design_managed_image_capability;
CREATE TABLE design_managed_image.sources(digest text PRIMARY KEY,owner_key text NOT NULL,media_id text NOT NULL,record jsonb NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(owner_key,media_id));
CREATE UNIQUE INDEX managed_source_object ON design_managed_image.sources ((record->'object'));
CREATE TABLE design_managed_image.preflights(source_digest text PRIMARY KEY REFERENCES design_managed_image.sources,record jsonb NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE design_managed_image.receipts(id text PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('storage','processing','cost')),owner_key text NOT NULL,request_id text NOT NULL,binding jsonb NOT NULL,budget jsonb,issued_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(kind,owner_key,request_id));
CREATE TABLE design_managed_image.claims(owner_key text NOT NULL,request_id text NOT NULL,intent jsonb NOT NULL,processing_id text NOT NULL REFERENCES design_managed_image.receipts,cost_id text NOT NULL REFERENCES design_managed_image.receipts,claimed_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(owner_key,request_id));
CREATE TABLE design_managed_image.upload_claims(owner_key text NOT NULL,request_id text NOT NULL,intent jsonb NOT NULL,receipt_id text NOT NULL REFERENCES design_managed_image.receipts,PRIMARY KEY(owner_key,request_id));
CREATE TABLE design_managed_image.responses(source_digest text NOT NULL REFERENCES design_managed_image.sources,request_id text NOT NULL,record jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(source_digest,request_id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['sources','preflights','receipts','claims','responses','upload_claims'] LOOP EXECUTE format('ALTER TABLE design_managed_image.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE design_managed_image.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY capability_only ON design_managed_image.%I TO design_managed_image_capability USING(true) WITH CHECK(true)',t);EXECUTE format('GRANT SELECT,INSERT ON design_managed_image.%I TO design_managed_image_capability',t);END LOOP;END$$;
GRANT UPDATE(active) ON design_managed_image.sources,design_managed_image.preflights,design_managed_image.receipts TO design_managed_image_capability;
CREATE FUNCTION design_managed_image.immutable_row() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF (TG_OP='DELETE' OR (to_jsonb(NEW)-'active') IS DISTINCT FROM (to_jsonb(OLD)-'active') OR to_jsonb(OLD)->'active'='false'::jsonb AND to_jsonb(NEW)->'active'='true'::jsonb) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_IMMUTABLE' USING ERRCODE='42501';END IF;RETURN NEW;END$$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['sources','preflights','receipts','claims','responses','upload_claims'] LOOP EXECUTE format('CREATE TRIGGER managed_immutable BEFORE UPDATE OR DELETE ON design_managed_image.%I FOR EACH ROW EXECUTE FUNCTION design_managed_image.immutable_row()',t);END LOOP;END$$;
CREATE FUNCTION design_managed_image.exact(v jsonb,keys text[]) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT coalesce(jsonb_typeof(v)='object' AND (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(v) k)=(SELECT array_agg(k ORDER BY k) FROM unnest(keys) k),false)$$;
CREATE FUNCTION design_managed_image.strings(v jsonb,keys text[]) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT coalesce(bool_and(jsonb_typeof(v->k) IS NOT DISTINCT FROM 'string'),false) FROM unnest(keys) k$$;
CREATE FUNCTION design_managed_image.owner_key(a jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT design_dependency_authority.digest(jsonb_build_array(a->'subjectId',a->'employmentId',a->'membershipId',a->'storeId',a->'scope'))$$;
CREATE FUNCTION design_managed_image.auth() RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF (session_user<>'design_identity_runtime') IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED' USING ERRCODE='42501';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));RETURN design_identity.require_authority();END$$;
CREATE FUNCTION design_managed_image.issuer_auth(credential text,scope jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE r jsonb;BEGIN IF (session_user NOT IN ('design_managed_storage_issuer','design_managed_processing_issuer','design_managed_cost_issuer','design_managed_preflight_issuer') OR credential IS NULL OR length(credential) NOT BETWEEN 32 AND 200 OR credential~'[[:space:][:cntrl:]]') IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED' USING ERRCODE='42501';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));r:=design_identity.resolve_hash(encode(sha256(convert_to(credential,'UTF8')),'hex'),scope);IF ((r->>'expiresAt')::timestamptz<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED' USING ERRCODE='42501';END IF;RETURN r->'authority';END$$;
CREATE FUNCTION design_managed_image.check_source(r jsonb,a jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF (NOT design_managed_image.strings(r,ARRAY['schemaVersion','mediaId','requestId','stage','angle','state','validation']) OR NOT design_managed_image.strings(r->'object',ARRAY['projectOrigin','bucket','key','version']) OR NOT design_managed_image.strings(r->'source',ARRAY['sha256','mime']) OR jsonb_path_exists(r,'$.** ? (@ == null)') OR jsonb_typeof(r->'source'->'byteLength') IS DISTINCT FROM 'number' OR r->'source'->>'byteLength'!~'^[1-9][0-9]*$' OR NOT design_managed_image.exact(r,ARRAY['schemaVersion','mediaId','requestId','owner','object','source','stage','angle','state','validation','publicEligible']) OR r->>'schemaVersion'<>'design-managed-image-source-v1' OR r->'owner' IS DISTINCT FROM a OR r->>'mediaId'!~'^[A-Za-z0-9_-]{1,100}$' OR r->>'requestId'!~'^[A-Za-z0-9_-]{1,100}$' OR r->>'stage' NOT IN ('before','after','reference') OR r->>'angle' NOT IN ('front','back','left','right','detail') OR r->>'state'<>'quarantined' OR r->>'validation'<>'not_performed' OR r->'publicEligible'<>'false'::jsonb
 OR NOT design_managed_image.exact(r->'object',ARRAY['projectOrigin','bucket','key','version']) OR r->'object'->>'projectOrigin'!~'^https://[a-z0-9-]+\.supabase\.co$' OR r->'object'->>'bucket'!~'^[A-Za-z0-9_-]{1,100}$' OR r->'object'->>'version'!~'^[A-Za-z0-9._-]{1,160}$' OR length(r->'object'->>'key') NOT BETWEEN 1 AND 1024 OR r->'object'->>'key'!~'^[A-Za-z0-9_][A-Za-z0-9_./-]*$' OR r->'object'->>'key'~'(^|/)(\.\.?|)($|/)'
 OR NOT design_managed_image.exact(r->'source',ARRAY['sha256','byteLength','mime']) OR r->'source'->>'sha256'!~'^[a-f0-9]{64}$' OR (r->'source'->>'byteLength')::bigint NOT BETWEEN 1 AND 8388608 OR r->'source'->>'mime' NOT IN ('image/jpeg','image/png','image/webp')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_SOURCE_INVALID' USING ERRCODE='42501';END IF;
 RETURN design_dependency_authority.digest(r);END$$;
CREATE FUNCTION design_managed_image.source_row(a jsonb,media text) RETURNS design_managed_image.sources LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE r design_managed_image.sources;BEGIN SELECT * INTO STRICT r FROM design_managed_image.sources WHERE owner_key=design_managed_image.owner_key(a) AND media_id=media FOR SHARE;IF (NOT r.active OR r.record->'owner' IS DISTINCT FROM a OR r.digest IS DISTINCT FROM design_managed_image.check_source(r.record,a)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_SOURCE_DENIED' USING ERRCODE='42501';END IF;RETURN r;END$$;
CREATE FUNCTION design_managed_image.transform_source(a jsonb,media text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE s design_managed_image.sources;p jsonb;r jsonb;BEGIN s:=design_managed_image.source_row(a,media);SELECT record INTO STRICT p FROM design_managed_image.preflights WHERE source_digest=s.digest AND active FOR SHARE;r:=s.record;RETURN jsonb_build_object('authority',a,'mediaId',media,'projectOrigin',r->'object'->'projectOrigin','bucket',r->'object'->'bucket','objectKey',r->'object'->'key','objectVersion',r->'object'->'version','expectedSourceSha256',r->'source'->'sha256','mime',r->'source'->'mime','byteLength',r->'source'->'byteLength','width',p->'display'->'width','height',p->'display'->'height','orientation','confirmed','immutable',true,'active',true);END$$;
CREATE FUNCTION design_managed_image.check_intent(i jsonb,a jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE s jsonb;scale numeric;t jsonb;BEGIN
 IF (NOT design_managed_image.strings(i,ARRAY['schemaVersion','requestId','purpose','recipient','bucket']) OR jsonb_path_exists(i,'$.** ? (@ == null)') OR jsonb_typeof(i->'maxEdge') IS DISTINCT FROM 'number' OR i->>'maxEdge'!~'^[1-9][0-9]*$' OR jsonb_typeof(i->'maxResponseBytes') IS DISTINCT FROM 'number' OR i->>'maxResponseBytes'!~'^[1-9][0-9]*$' OR NOT design_managed_image.exact(i,ARRAY['schemaVersion','requestId','purpose','recipient','bucket','source','maxEdge','transform','maxResponseBytes']) OR i->>'schemaVersion'<>'design-managed-image-transform-intent-v1' OR i->>'requestId'!~'^[A-Za-z0-9_-]{1,100}$' OR i->>'purpose'<>'private_image_managed_transform_quarantine' OR (i->>'maxEdge')::int NOT IN (1024,1536) OR (i->>'maxResponseBytes')::int NOT BETWEEN 1 AND 8388608) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_INTENT_INVALID' USING ERRCODE='42501';END IF;
 s:=design_managed_image.transform_source(a,i->'source'->>'mediaId');scale:=least(1,(i->>'maxEdge')::numeric/greatest((s->>'width')::numeric,(s->>'height')::numeric));t:=jsonb_build_object('width',greatest(1,floor((s->>'width')::numeric*scale)),'height',greatest(1,floor((s->>'height')::numeric*scale)),'resize','contain','format','origin','quality',80);
 IF (i->'source' IS DISTINCT FROM s OR i->'recipient' IS DISTINCT FROM s->'projectOrigin' OR i->'bucket' IS DISTINCT FROM s->'bucket' OR i->'transform' IS DISTINCT FROM t) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_INTENT_INVALID' USING ERRCODE='42501';END IF;RETURN design_managed_image.owner_key(a);END$$;
CREATE FUNCTION design_managed_image.receipt(a jsonb,k text,rid text,b jsonb) RETURNS design_managed_image.receipts LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE r design_managed_image.receipts;BEGIN SELECT * INTO STRICT r FROM design_managed_image.receipts WHERE kind=k AND owner_key=design_managed_image.owner_key(a) AND request_id=rid FOR SHARE;IF (NOT r.active OR r.binding IS DISTINCT FROM b OR r.issued_at>clock_timestamp() OR r.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_RECEIPT_DENIED' USING ERRCODE='42501';END IF;RETURN r;END$$;
CREATE FUNCTION design_managed_image.live(i jsonb,a jsonb,phase text) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE k text;p design_managed_image.receipts;c design_managed_image.receipts;cl design_managed_image.claims;BEGIN
 k:=design_managed_image.check_intent(i,a);p:=design_managed_image.receipt(a,'processing',i->>'requestId',i);c:=design_managed_image.receipt(a,'cost',i->>'requestId',i);
 -- Claims are append-only with immutable triggers and share the authorization transaction advisory lock. No UPDATE privilege is granted for a read lock.
 SELECT * INTO cl FROM design_managed_image.claims WHERE owner_key=k AND request_id=i->>'requestId';
 IF (phase IN ('before_transport','after_response') AND cl.owner_key IS NULL OR cl.owner_key IS NOT NULL AND (cl.intent IS DISTINCT FROM i OR cl.processing_id<>p.id OR cl.cost_id<>c.id)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_CLAIM_DENIED' USING ERRCODE='42501';END IF;
 IF (design_managed_image.auth() IS DISTINCT FROM a OR p.expires_at<=clock_timestamp() OR c.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED' USING ERRCODE='42501';END IF;RETURN true;END$$;
CREATE FUNCTION design_managed_image.resolve_source(media text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;v jsonb;BEGIN a:=design_managed_image.auth();v:=design_managed_image.transform_source(a,media);IF (design_managed_image.auth() IS DISTINCT FROM a) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED';END IF;RETURN v;END$$;
CREATE FUNCTION design_managed_image.guard(i jsonb,phase text,kind text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r design_managed_image.receipts;BEGIN a:=design_managed_image.auth();IF (phase NOT IN ('before_claim','before_transport','after_response') OR kind NOT IN ('processing','cost','all')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED' USING ERRCODE='42501';END IF;IF kind='all' THEN RETURN design_managed_image.live(i,a,phase);END IF;PERFORM design_managed_image.check_intent(i,a);r:=design_managed_image.receipt(a,kind,i->>'requestId',i);IF (design_managed_image.auth() IS DISTINCT FROM a OR r.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED';END IF;RETURN true;END$$;
CREATE FUNCTION design_managed_image.claim(i jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;k text;p design_managed_image.receipts;c design_managed_image.receipts;BEGIN a:=design_managed_image.auth();PERFORM design_managed_image.live(i,a,'before_claim');k:=design_managed_image.owner_key(a);IF EXISTS(SELECT 1 FROM design_managed_image.claims WHERE owner_key=k AND request_id=i->>'requestId') THEN RETURN 'already_claimed';END IF;p:=design_managed_image.receipt(a,'processing',i->>'requestId',i);c:=design_managed_image.receipt(a,'cost',i->>'requestId',i);INSERT INTO design_managed_image.claims(owner_key,request_id,intent,processing_id,cost_id) VALUES(k,i->>'requestId',i,p.id,c.id);PERFORM design_managed_image.live(i,a,'before_transport');RETURN 'created';END$$;
CREATE FUNCTION design_managed_image.check_upload(i jsonb,a jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE r jsonb;b jsonb;BEGIN
 IF (NOT design_managed_image.strings(i,ARRAY['schemaVersion','requestId','mediaId','stage','angle']) OR NOT design_managed_image.exact(i,ARRAY['schemaVersion','requestId','mediaId','authority','target','source','stage','angle','cost']) OR i->>'schemaVersion'<>'design-managed-image-upload-intent-v1' OR i->'authority' IS DISTINCT FROM a OR NOT design_managed_image.exact(i->'target',ARRAY['projectOrigin','bucket','key'])) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_UPLOAD_INVALID' USING ERRCODE='42501';END IF;
 r:=jsonb_build_object('schemaVersion','design-managed-image-source-v1','mediaId',i->'mediaId','requestId',i->'requestId','owner',a,'object',i->'target'||jsonb_build_object('version','structure-check-only'),'source',i->'source','stage',i->'stage','angle',i->'angle','state','quarantined','validation','not_performed','publicEligible',false);PERFORM design_managed_image.check_source(r,a);
 b:=i->'cost';IF (NOT design_managed_image.exact(b,ARRAY['currency','maximumMinorUnits','maximumDispatches','commitment']) OR jsonb_path_exists(b,'$.** ? (@ == null)') OR b->>'currency'!~'^[A-Z]{3}$' OR jsonb_typeof(b->'maximumMinorUnits') IS DISTINCT FROM 'number' OR b->>'maximumMinorUnits'!~'^[1-9][0-9]*$' OR (b->>'maximumMinorUnits')::bigint NOT BETWEEN 1 AND 100000000 OR b->'maximumDispatches'<>'1'::jsonb OR b->>'commitment'<>'one_time') IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_COST_INVALID';END IF;RETURN true;END$$;
CREATE FUNCTION design_managed_image.storage_guard(i jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_managed_image.receipts;BEGIN a:=design_managed_image.auth();PERFORM design_managed_image.check_upload(i,a);p:=design_managed_image.receipt(a,'storage',i->>'requestId',i);IF (p.budget IS DISTINCT FROM i->'cost' OR design_managed_image.auth() IS DISTINCT FROM a OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED';END IF;RETURN true;END$$;
CREATE FUNCTION design_managed_image.claim_upload(i jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_managed_image.receipts;old jsonb;BEGIN a:=design_managed_image.auth();PERFORM design_managed_image.storage_guard(i);SELECT intent INTO old FROM design_managed_image.upload_claims WHERE owner_key=design_managed_image.owner_key(a) AND request_id=i->>'requestId';IF FOUND THEN IF (old IS DISTINCT FROM i) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_UPLOAD_CONFLICT';END IF;RETURN 'already_claimed';END IF;p:=design_managed_image.receipt(a,'storage',i->>'requestId',i);INSERT INTO design_managed_image.upload_claims VALUES(design_managed_image.owner_key(a),i->>'requestId',i,p.id);PERFORM design_managed_image.storage_guard(i);RETURN 'created';END$$;
CREATE FUNCTION design_managed_image.publish_source(r jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;d text;old design_managed_image.sources;u design_managed_image.upload_claims;p design_managed_image.receipts;BEGIN a:=design_managed_image.auth();d:=design_managed_image.check_source(r,a);SELECT * INTO STRICT u FROM design_managed_image.upload_claims WHERE owner_key=design_managed_image.owner_key(a) AND request_id=r->>'requestId';PERFORM design_managed_image.storage_guard(u.intent);p:=design_managed_image.receipt(a,'storage',r->>'requestId',u.intent);
 IF (u.receipt_id<>p.id OR u.intent->'authority' IS DISTINCT FROM r->'owner' OR u.intent->'mediaId' IS DISTINCT FROM r->'mediaId' OR u.intent->'target' IS DISTINCT FROM ((r->'object')-'version') OR u.intent->'source' IS DISTINCT FROM r->'source' OR u.intent->'stage' IS DISTINCT FROM r->'stage' OR u.intent->'angle' IS DISTINCT FROM r->'angle') IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_SOURCE_CONFLICT';END IF;
 SELECT * INTO old FROM design_managed_image.sources WHERE owner_key=design_managed_image.owner_key(a) AND media_id=r->>'mediaId';IF FOUND THEN IF (NOT old.active OR old.record IS DISTINCT FROM r) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_SOURCE_CONFLICT' USING ERRCODE='42501';END IF;ELSE INSERT INTO design_managed_image.sources VALUES(d,design_managed_image.owner_key(a),r->>'mediaId',r,true);END IF;PERFORM design_managed_image.storage_guard(u.intent);RETURN r;END$$;
CREATE FUNCTION design_managed_image.issue_preflight(credential text,scope jsonb,p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;s design_managed_image.sources;old jsonb;BEGIN
 IF (session_user<>'design_managed_preflight_issuer') IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED' USING ERRCODE='42501';END IF;a:=design_managed_image.issuer_auth(credential,scope);SELECT * INTO STRICT s FROM design_managed_image.sources WHERE digest=p->>'sourceRecordDigest' AND active;PERFORM design_managed_image.check_source(s.record,a);
 IF (NOT design_managed_image.strings(p,ARRAY['schemaVersion','id','sourceRecordDigest','sourceVersion','verifiedSourceSha256']) OR NOT design_managed_image.strings(p->'verifier',ARRAY['id','version']) OR jsonb_path_exists(p,'$.** ? (@ == null)') OR jsonb_typeof(p->'display'->'width') IS DISTINCT FROM 'number' OR p->'display'->>'width'!~'^[1-9][0-9]*$' OR jsonb_typeof(p->'display'->'height') IS DISTINCT FROM 'number' OR p->'display'->>'height'!~'^[1-9][0-9]*$' OR NOT design_managed_image.exact(p,ARRAY['schemaVersion','id','sourceRecordDigest','sourceVersion','verifiedSourceSha256','verifier','display','checks']) OR p->>'schemaVersion'<>'design-managed-image-preflight-v1' OR p->>'id'!~'^[A-Za-z0-9_-]{1,100}$' OR p->'sourceVersion' IS DISTINCT FROM s.record->'object'->'version' OR p->'verifiedSourceSha256' IS DISTINCT FROM s.record->'source'->'sha256' OR p->'checks' IS DISTINCT FROM '{"sourceBinding":"verified","orientation":"verified","displayDimensions":"verified"}'::jsonb OR NOT design_managed_image.exact(p->'display',ARRAY['width','height']) OR (p->'display'->>'width')::int NOT BETWEEN 1 AND 16384 OR (p->'display'->>'height')::int NOT BETWEEN 1 AND 16384 OR (p->'display'->>'width')::bigint*(p->'display'->>'height')::bigint>40000000 OR NOT design_managed_image.exact(p->'verifier',ARRAY['id','version']) OR p->'verifier'->>'id'!~'^[A-Za-z0-9_-]{1,100}$' OR p->'verifier'->>'version'!~'^[A-Za-z0-9._-]{1,160}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_PREFLIGHT_INVALID' USING ERRCODE='42501';END IF;
 SELECT record INTO old FROM design_managed_image.preflights WHERE source_digest=s.digest;IF FOUND THEN IF (old IS DISTINCT FROM p OR NOT EXISTS(SELECT 1 FROM design_managed_image.preflights WHERE source_digest=s.digest AND active)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_PREFLIGHT_CONFLICT';END IF;ELSE INSERT INTO design_managed_image.preflights VALUES(s.digest,p,true);END IF;IF (design_managed_image.issuer_auth(credential,scope) IS DISTINCT FROM a) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED';END IF;RETURN p;END$$;
CREATE FUNCTION design_managed_image.issue_receipt(credential text,scope jsonb,id text,kind text,binding jsonb,budget jsonb,ttl bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;k text;rid text;r design_managed_image.receipts;now_at timestamptz;BEGIN
 budget:=coalesce(budget,'null'::jsonb);
 IF (kind NOT IN ('storage','processing','cost') OR session_user IS DISTINCT FROM ('design_managed_'||kind||'_issuer') OR id!~'^[A-Za-z0-9_-]{1,100}$' OR ttl NOT BETWEEN 1 AND 900000) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED' USING ERRCODE='42501';END IF;a:=design_managed_image.issuer_auth(credential,scope);k:=design_managed_image.owner_key(a);rid:=binding->>'requestId';
 IF kind='storage' THEN PERFORM design_managed_image.check_upload(binding,a);ELSE PERFORM design_managed_image.check_intent(binding,a);END IF;
 IF kind IN ('cost','storage') THEN IF (jsonb_path_exists(budget,'$.** ? (@ == null)') OR jsonb_typeof(budget->'maximumMinorUnits') IS DISTINCT FROM 'number' OR NOT design_managed_image.exact(budget,ARRAY['currency','maximumMinorUnits','maximumDispatches','commitment']) OR budget->>'currency'!~'^[A-Z]{3}$' OR budget->>'maximumMinorUnits'!~'^[1-9][0-9]*$' OR (budget->>'maximumMinorUnits')::bigint NOT BETWEEN 1 AND 100000000 OR budget->'maximumDispatches'<>'1'::jsonb OR budget->>'commitment'<>'one_time') IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_COST_INVALID';END IF;ELSIF budget IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'MANAGED_BUDGET_INVALID';END IF;
 IF (kind='storage' AND budget IS DISTINCT FROM binding->'cost') IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_BUDGET_INVALID';END IF;
 IF (EXISTS(SELECT 1 FROM design_managed_image.claims WHERE owner_key=k AND request_id=rid) OR EXISTS(SELECT 1 FROM design_managed_image.upload_claims WHERE owner_key=k AND request_id=rid)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_ALREADY_CLAIMED';END IF;
 now_at:=clock_timestamp();INSERT INTO design_managed_image.receipts VALUES(id,kind,k,rid,binding,budget,now_at,now_at+ttl*interval '1 millisecond',true) RETURNING * INTO r;
 IF (design_managed_image.issuer_auth(credential,scope) IS DISTINCT FROM a OR r.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED';END IF;RETURN jsonb_build_object('receiptId',r.id,'kind',r.kind,'binding',r.binding,'budget',r.budget,'issuedAt',floor(extract(epoch FROM r.issued_at)*1000),'expiresAt',floor(extract(epoch FROM r.expires_at)*1000));END$$;
CREATE FUNCTION design_managed_image.revoke(kind text,id text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE n bigint;BEGIN IF (kind NOT IN ('storage','processing','cost','preflight') OR session_user IS DISTINCT FROM ('design_managed_'||kind||'_issuer')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED' USING ERRCODE='42501';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));IF kind='preflight' THEN UPDATE design_managed_image.preflights SET active=false WHERE source_digest=id AND active;ELSE UPDATE design_managed_image.receipts SET active=false WHERE receipts.id=revoke.id AND receipts.kind=revoke.kind AND active;END IF;GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;END$$;
CREATE FUNCTION design_managed_image.check_response(a jsonb,sd text,d jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE s design_managed_image.sources;i jsonb;src jsonb;expected jsonb;BEGIN
 SELECT * INTO STRICT s FROM design_managed_image.sources WHERE digest=sd AND active;PERFORM design_managed_image.check_source(s.record,a);SELECT intent INTO STRICT i FROM design_managed_image.claims WHERE owner_key=design_managed_image.owner_key(a) AND request_id=d->>'requestId';PERFORM design_managed_image.live(i,a,'after_response');src:=i->'source';
 expected:=jsonb_build_object('bindingDigest',design_dependency_authority.digest(src),'objectVersion',src->'objectVersion','expectedSourceSha256',src->'expectedSourceSha256','mime',src->'mime','byteLength',src->'byteLength','width',src->'width','height',src->'height','orientation','confirmed');
 IF (NOT design_managed_image.strings(d,ARRAY['schemaVersion','state','requestId','mediaId']) OR jsonb_path_exists(d,'$.** ? (@ == null)') OR i->'source' IS DISTINCT FROM design_managed_image.transform_source(a,s.record->>'mediaId') OR jsonb_typeof(d->'derivative'->'sha256') IS DISTINCT FROM 'string' OR jsonb_typeof(d->'derivative'->'byteLength') IS DISTINCT FROM 'number' OR d->'derivative'->>'byteLength'!~'^[1-9][0-9]*$' OR jsonb_typeof(d->'derivative'->'mime') IS DISTINCT FROM 'string' OR NOT design_managed_image.exact(d,ARRAY['schemaVersion','state','requestId','mediaId','source','requestedTransform','derivative','validation']) OR d->>'schemaVersion'<>'design-managed-image-transform-v1' OR d->>'state'<>'pending_validation' OR d->'mediaId' IS DISTINCT FROM s.record->'mediaId' OR d->'source' IS DISTINCT FROM expected OR d->'requestedTransform' IS DISTINCT FROM (i->'transform'||jsonb_build_object('maxEdge',i->'maxEdge')) OR d->'validation' IS DISTINCT FROM '{"sourceBytes":"not_verified","immutableObject":"trusted_resolver_assertion","derivativeSource":"not_verified","fullDecode":"not_verified","metadataRemoval":"not_verified","orientation":"not_verified","color":"not_verified","geometry":"not_verified","candidateEligible":false,"publicEligible":false}'::jsonb OR NOT design_managed_image.exact(d->'derivative',ARRAY['sha256','byteLength','mime']) OR d->'derivative'->>'sha256'!~'^[a-f0-9]{64}$' OR (d->'derivative'->>'byteLength')::bigint NOT BETWEEN 1 AND (i->>'maxResponseBytes')::bigint OR d->'derivative'->'mime' IS DISTINCT FROM src->'mime') IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_RESPONSE_DENIED' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('schemaVersion','design-managed-image-response-v1','sourceRecordDigest',sd,'descriptor',d);END$$;
CREATE FUNCTION design_managed_image.publish_response(sd text,d jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r jsonb;old jsonb;BEGIN a:=design_managed_image.auth();r:=design_managed_image.check_response(a,sd,d);SELECT record INTO old FROM design_managed_image.responses WHERE source_digest=sd AND request_id=d->>'requestId';IF FOUND THEN IF (old IS DISTINCT FROM r) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_RESPONSE_CONFLICT';END IF;ELSE INSERT INTO design_managed_image.responses(source_digest,request_id,record) VALUES(sd,d->>'requestId',r);END IF;PERFORM design_managed_image.check_response(design_managed_image.auth(),sd,d);RETURN r;END$$;
CREATE FUNCTION design_managed_image.read_status(media text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;s design_managed_image.sources;r jsonb;BEGIN a:=design_managed_image.auth();IF NOT EXISTS(SELECT 1 FROM design_managed_image.sources WHERE owner_key=design_managed_image.owner_key(a) AND media_id=media) THEN RETURN jsonb_build_object('sourceRecord',null,'response',null);END IF;s:=design_managed_image.source_row(a,media);SELECT record INTO r FROM design_managed_image.responses WHERE source_digest=s.digest ORDER BY created_at DESC,request_id DESC LIMIT 1;IF r IS NOT NULL THEN PERFORM design_managed_image.check_response(a,s.digest,r->'descriptor');END IF;IF (design_managed_image.auth() IS DISTINCT FROM a) IS DISTINCT FROM false THEN RAISE EXCEPTION 'MANAGED_DENIED';END IF;RETURN jsonb_build_object('sourceRecord',s.record,'response',r);END$$;
DO $$DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='design_managed_image' LOOP EXECUTE format('ALTER FUNCTION %s OWNER TO design_managed_image_capability',f.sig);EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,design_identity_runtime,design_managed_storage_issuer,design_managed_processing_issuer,design_managed_cost_issuer,design_managed_preflight_issuer',f.sig);END LOOP;END$$;
GRANT EXECUTE ON FUNCTION design_managed_image.resolve_source(text),design_managed_image.guard(jsonb,text,text),design_managed_image.claim(jsonb),design_managed_image.storage_guard(jsonb),design_managed_image.claim_upload(jsonb),design_managed_image.publish_source(jsonb),design_managed_image.publish_response(text,jsonb),design_managed_image.read_status(text) TO design_identity_runtime;
GRANT EXECUTE ON FUNCTION design_managed_image.issue_preflight(text,jsonb,jsonb) TO design_managed_preflight_issuer;
GRANT EXECUTE ON FUNCTION design_managed_image.issue_receipt(text,jsonb,text,text,jsonb,jsonb,bigint) TO design_managed_storage_issuer,design_managed_processing_issuer,design_managed_cost_issuer;
GRANT EXECUTE ON FUNCTION design_managed_image.revoke(text,text) TO design_managed_storage_issuer,design_managed_processing_issuer,design_managed_cost_issuer,design_managed_preflight_issuer;
REVOKE ALL ON ALL TABLES IN SCHEMA design_managed_image FROM PUBLIC,anon,authenticated,design_identity_runtime,design_managed_storage_issuer,design_managed_processing_issuer,design_managed_cost_issuer,design_managed_preflight_issuer;

REVOKE CREATE ON SCHEMA design_managed_image FROM design_managed_image_capability;
